<!--
  OrderedListMenu: shown when the user clicks the number marker of an
  ordered-list block.

  Three items:
    • Continue numbering from previous (disabled if previous sibling is not
      an ordered-list item). This clears any explicit `startNumber` override.
    • Start new list (from 1). This sets `startNumber = 1` on this block,
      which also acts as a boundary for following ordered-list items.
    • Modify number value — opens the NumberPicker popup.
-->

<template>
  <Teleport to="body">
    <div
      v-if="visible && anchor && rootEl"
      ref="menuEl"
      class="ordered-list-menu"
      :class="{ above: placement.above }"
      :style="menuStyle"
      role="menu"
      @mousedown.prevent.stop
    >
      <button
        class="olm-item"
        :class="{ disabled: !canContinue }"
        role="menuitem"
        @click="onContinue"
