</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import type { BlockId } from '../../core/types';
import { useI18n } from '../../i18n';

const props = defineProps<{
  visible: boolean;
  blockId: BlockId | null;
  /** The marker element that was clicked (serves as anchor). */
  anchor: HTMLElement | null;
  rootEl: HTMLElement | null;
  /** True if the previous block in document order is an ordered-list item. */
  canContinue: boolean;
  /** True if "Start new list" is actionable (current ordinal is not 1). */
  canStartNew: boolean;
  /** The currently displayed ordinal of this block (for the picker default). */
  currentNumber: number;
}>();

const emit = defineEmits<{
  /** "Continue previous" — clear startNumber override. */
  continue: [];
  /** "Start new list" — set startNumber to 1. */
  startNew: [];
  /** "Modify number value" — asks the host to show the number picker. */
  modify: [initialValue: number];
  close: [];
}>();

const { t } = useI18n();

const menuEl = ref<HTMLElement | null>(null);
const placement = ref({ top: 0, left: 0, above: false });
const MARGIN = 6;

watch(
  [() => props.visible, () => props.anchor, menuEl],
  async () => {
    if (!props.visible || !props.anchor) return;
    await nextTick();
    const el = menuEl.value;
    if (!el) return;
    const aRect = props.anchor.getBoundingClientRect();
    const mRect = el.getBoundingClientRect();
    const vh = window.innerHeight;
    const spaceBelow = vh - aRect.bottom - MARGIN;
    const spaceAbove = aRect.top - MARGIN;
    const h = Math.max(mRect.height, 10);
    let above = false;
    if (spaceBelow >= h) {
      above = false;
    } else if (spaceAbove >= h) {
      above = true;
    } else {
      above = spaceAbove > spaceBelow;
    }
    placement.value = {
      top: above
        ? aRect.top - (mRect.height + MARGIN)
        : aRect.bottom + MARGIN,
      left: aRect.left,
      above,
    };
  },
  { flush: 'post', immediate: true },
);

const menuStyle = computed(() => ({
  top: `${placement.value.top}px`,
  left: `${placement.value.left}px`,
}));

function onContinue(): void {
  if (!props.canContinue) return;
  emit('continue');
}
function onStartNew(): void {
  if (!props.canStartNew) return;
  emit('startNew');
}
function onModify(): void {
  emit('modify', props.currentNumber);
}
</script>
